import{_ as n,o as a,c as l,ag as t}from"./chunks/framework.PVHj0As1.js";const p="/pub-blog/assets/image-20250512141246931.DneTM_rn.png",e="/pub-blog/assets/image-20250512141412706.H3NvJcXT.png",h="/pub-blog/assets/PixPin_2025-05-12_14-49-23.79Xhgir7.gif",k="/pub-blog/assets/PixPin_2025-05-12_17-40-53.9bBxv243.gif",i="/pub-blog/assets/PixPin_2025-05-12_15-47-09.B5W60aAM.gif",r="/pub-blog/assets/image-20250512172354900.DLVmpeaA.png",E="/pub-blog/assets/image-20250512190304099.rt3TShZM.png",d="/pub-blog/assets/image-20250512190623863.C301bzFN.png",o="/pub-blog/assets/image-20250512211855945.S4hLb2zz.png",g="/pub-blog/assets/PixPin_2025-05-12_21-28-06.C5nW4oNw.gif",B=JSON.parse('{"title":"HarmonyOS Next 优雅的路由跳转方案 ZRouter","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 路由跳转 ZRouter/HarmonyOS Next 路由跳转 ZRouter.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 路由跳转 ZRouter/HarmonyOS Next 路由跳转 ZRouter.md","lastUpdated":1747069056000,"__rawMarkdown":"# HarmonyOS Next 优雅的路由跳转方案 ZRouter\\n\\n## 前言\\n\\n目前鸿蒙应用开发中，官方的路由跳转方案是\\n\\n1. ~~Router 不推荐~~\\n2. **Navigation 推荐**\\n\\n然后 HMRouter 和 ZRouter 都是基于 Navigation 做的封装。\\n\\n## 介绍\\n\\n[ZRouter](https://ohpm.openharmony.cn/#/cn/detail/@hzw%2Fzrouter)是一款轻量级且非侵入性的鸿蒙动态路由框架，目前在三方库上已有**4,671 的下载量**，也是鸿蒙生态中很流行的路由管理库。![image-20250512141246931](assets/image-20250512141246931.png)\\n\\n也是 gitcode 上 G_Star 项目\\n\\n![image-20250512141412706](assets/image-20250512141412706.png)\\n\\nZRouter 已上架录入到[华为鸿蒙生态伙伴组件专区](https://developer.huawei.com/consumer/cn/market/landing/component)\\n\\n## 特性\\n\\nZRouter 具有以下优点：\\n\\n- 简单易用\\n- 支持 V1 状态管理和 V2 状态管理；\\n- **支持 API 链式调用，让 API 更简洁直观；**\\n- **支持 NavDestination 页面模板化**\\n- 注解参数支持使用静态常量，可跨模块定义；\\n- 支持自定义与全局拦截器，可设优先级及中断逻辑，可实现页面重定向、登录验证等业务场景。\\n- **支持服务路由，可实现 Har/Hsp 模块间的通信；**\\n- 支持全局及单个页面的生命周期函数管理，可使任意类都能享有与组件相同的生命周期特性，可实现页面埋点统计等业务场景；\\n- **支持跨多级页面参数携带返回监听；**\\n- 支持自定义 URL 路径跳转，可在拦截器内自行解析 URL 实现业务逻辑；\\n- **内置多种转场动画效果（平移、旋转、渐变、缩放、高斯模糊），并支持自定义动画；**\\n- 支持启动模式、混淆、嵌套 Navigation、Hap；\\n- 支持第三方 Navigation 的使用本库 API；\\n- **支持与您现有项目中的 Navigation 无缝融合，实现零成本向本库迁移；**\\n- 支持 ArkUI-X 跨平台上使用；\\n- 未来计划：支持共享元素动画、持续优化\\n\\n## 快速上手\\n\\n### 1. 项目中配置**router-register-plugin**插件\\n\\n```json\\n// hvigor/hvigor-config.json5\\n  \\"dependencies\\": {\\n    \\"router-register-plugin\\":\\"1.3.2\\"\\n  },\\n```\\n\\n### 2. 在模块（har、hsp、hap 都可以）的 hvigorfile.ts 文件导入 router-register-plugin 插件，如在 Entry 中进行配置\\n\\n```typescript\\n// entry/hvigorfile.ts\\nimport { hapTasks } from \\"@ohos/hvigor-ohos-plugin\\";\\nimport { routerRegisterPlugin, PluginConfig } from \\"router-register-plugin\\";\\n// 2、初始化配置\\nconst config: PluginConfig = {\\n  scanDirs: [\\"src/main/ets/pages\\", \\"src/main/ets/views\\"], // 扫描的目录，如果不设置，默认是扫描src/main/ets目录\\n  logEnabled: true, // 查看日志\\n  viewNodeInfo: false, // 查看节点信息\\n  isAutoDeleteHistoryFiles: true, // 删除无用编译产物\\n  lifecycleObserverAttributeName: \\"xxx\\", // 可选，设置全局的生命周期实现类在组件上的属性名，默认值是lifecycleObserver\\n};\\nexport default {\\n  system: hapTasks /* Built-in plugin of Hvigor. It cannot be modified. */,\\n  plugins: [routerRegisterPlugin(config)],\\n};\\n```\\n\\n### 3. 在模块中，下载安装 ZRouter\\n\\n```\\nohpm install @hzw/zrouter\\n```\\n\\n### 4. 在 EntryAbility 的 onCreate()方法中初始化 ZRouter\\n\\n```typescript\\nonCreate(want: Want, launchParam: AbilityConstant.LaunchParam): void {\\n    this.context.getApplicationContext().setColorMode(ConfigurationConstant.ColorMode.COLOR_MODE_NOT_SET);\\n     ZRouter.initialize((config) => {\\n          // config.isLoggingEnabled = BuildProfile.DEBUG\\n          config.isHSPModuleDependent = true\\n    })\\n  }\\n```\\n\\n### 5. 将 page/Index.ets ，作为 ZRouter 的根容器，需要使用**Navigation**进行外层容器\\n\\n```typescript\\nimport { Route, ZRouter } from \'@hzw/zrouter\'\\n\\n@Entry\\n@Component\\nexport struct Index {\\n\\n  build() {\\n    // 获取NavPathStack实例对象\\n    Navigation(ZRouter.getNavStack()){\\n      Column({space:12}){\\n        Button(\'跳转到登录\').onClick((event: ClickEvent) => {\\n          ZRouter.getInstance().push(\\"Login\\")\\n        })\\n      }\\n    }\\n    .title(\'首页\')\\n    .height(\'100%\')\\n    .width(\'100%\')\\n  }\\n}\\n```\\n\\n### 6. 其他页面需要使用@Route 和 NavDestination 进行修饰\\n\\n```typescript\\n// entry/src/main/ets/pages/Login.ets\\nimport { Route, ZRouter } from \\"@hzw/zrouter\\";\\n\\n@Route({ name: \'Login\'})\\n@Component\\nexport struct Login {\\n\\n  build() {\\n    NavDestination(){\\n      Column({space:12}){\\n         Text(\\"登录的页面\\")\\n          // 返回使用pop方法\\n      }\\n    }\\n    .title(\'登录\')\\n    .width(\'100%\')\\n    .height(\'100%\')\\n\\n  }\\n}\\n```\\n\\n### 7. 效果\\n\\n![PixPin_2025-05-12_14-49-23](assets/PixPin_2025-05-12_14-49-23.gif)\\n\\n## 启动页的设置流程\\n\\n一般 app 的启动流程都是 启动页面->主页，这里因为使用了 pages/Index.ets 作为了根容器，所以当要实现启动页流程时，其实是需要用到 3 个页面。\\n\\n### 1. page/Index.ets 作为页面根容器\\n\\n```typescript\\n// entry/src/main/ets/pages/Index.ets\\nimport { Route, ZRouter } from \'@hzw/zrouter\'\\n\\n@Route({ name: \\"Index\\" })\\n@Entry\\n@Component\\nexport struct Index {\\n  build() {\\n    // 获取NavPathStack实例对象\\n    Navigation(ZRouter.getNavStack()) {\\n      Column({ space: 12 }) {\\n        Button(\'跳转到登录\').onClick((event: ClickEvent) => {\\n          ZRouter.getInstance().push(\\"Login\\")\\n        })\\n      }\\n    }\\n    .title(\'首页\')\\n    .height(\'100%\')\\n    .width(\'100%\')\\n    .onAppear(() => {\\n      // 跳转启动页\\n      ZRouter.getInstance().push(\\"Splash\\")\\n    })\\n    .hideTitleBar(true)\\n\\n  }\\n}\\n```\\n\\n### 2. 新建一个启动页 ，完成页面展示后，跳转到真正的业务首页\\n\\n```typescript\\n// entry/src/main/ets/pages/Splash.ets\\nimport { Route, ZRouter } from \\"@hzw/zrouter\\";\\n\\n@Route({ name: \\"Splash\\" })\\n@Component\\nexport struct Splash {\\n  build() {\\n    NavDestination() {\\n      Column() {\\n        Button(\'Splash 启动页\')\\n      }\\n      .width(\\"100%\\")\\n      .height(\\"100%\\")\\n      .justifyContent(FlexAlign.Center)\\n      .backgroundColor(Color.Yellow)\\n    }\\n    .onAppear(() => {\\n      // 模拟展示启动页\\n      setTimeout(() => {\\n        ZRouter.getInstance().navigation(\\"Login\\")\\n      }, 3000)\\n    })\\n  }\\n}\\n```\\n\\n### 3. 业务首页\\n\\n登录页面作为，业务中的首页\\n\\n```typescript\\n// entry/src/main/ets/pages/Login.ets\\nimport { Route, TranslateAnimationOptions, ZRouter } from \\"@hzw/zrouter\\";\\n\\n@Route({ name: \'Login\' })\\n@Component\\nexport struct Login {\\n  build() {\\n    NavDestination() {\\n      Column({ space: 12 }) {\\n        Text(\\"登录的页面\\")\\n      }\\n    }\\n    .title(\'登录\')\\n    .width(\'100%\')\\n    .height(\'100%\')\\n  }\\n}\\n```\\n\\n### 4. 效果\\n\\n![PixPin_2025-05-12_17-40-53](assets/PixPin_2025-05-12_17-40-53.gif)\\n\\n## 动画转场\\n\\nZRouter 也提供了页面切换的动画效果，主要有：\\n\\n1. 平移\\n2. 缩放\\n3. 旋转\\n4. 渐变\\n\\n[也可以自定义转场动画。](https://gitee.com/common-apps/ZRouter/wikis/%E8%B7%AF%E7%94%B1%E8%BD%AC%E5%9C%BA%E5%8A%A8%E7%94%BB)\\n\\n可以全局设置页面切换的动画，也可以单个页面设置。\\n\\n### 全局动画\\n\\n#### 1. 在容器页面设置全局动画\\n\\n```typescript\\nimport {\\n  OpacityAnimateOptions,\\n  RotateAnimateOptions,\\n  Route,\\n  ScaleAnimateOptions,\\n  TranslateAnimationOptions,\\n  ZRouter\\n} from \'@hzw/zrouter\'\\n\\n@Entry\\n@Component\\nexport struct Index {\\n  build() {\\n    // 获取NavPathStack实例对象\\n    Navigation(ZRouter.getNavStack()) {\\n      Column({ space: 12 }) {\\n        Button(\'跳转到登录\').onClick((event: ClickEvent) => {\\n          ZRouter.getInstance().push(\\"Login\\")\\n        })\\n      }\\n    }\\n    .title(\'首页\')\\n    .height(\'100%\')\\n    .width(\'100%\')\\n    .customNavContentTransition(\\n      ZRouter.animateMgr()// 创建默认动画管理器\\n        .defaultAnimateBuilder()// 设置进场动画参数\\n        .setEnterAnimate({ duration: 500 })// 设置退场动画参数\\n        .setExitAnimate({ duration: 700 })// 平移\\n          // .addAnimateOptions(new TranslateAnimationOptions({ x: \'50%\', y: \'50%\' }))// 渐变\\n        .addAnimateOptions(new OpacityAnimateOptions(0.01))// 缩放\\n          // .addAnimateOptions(new ScaleAnimateOptions({ x: 0, y: 0 }))// 旋转\\n          // .addAnimateOptions(new RotateAnimateOptions({ angle: 90 }))// 自定义转场动画回调\\n        .getAnimCustomNavContentTransition())\\n\\n  }\\n}\\n```\\n\\n#### 2. 在子页面注册和卸载动画\\n\\n比如，需要跳转到登录页面，那么就在登录页面注册和卸载动画\\n\\n```typescript\\n// entry/src/main/ets/pages/Login.ets\\nimport { Route, ZRouter } from \\"@hzw/zrouter\\";\\n\\n@Route({ name: \'Login\' })\\n@Component\\nexport struct Login {\\n  build() {\\n    NavDestination() {\\n      Column({ space: 12 }) {\\n        Text(\\"登录的页面\\")\\n      }\\n    }\\n    .title(\'登录\')\\n    .width(\'100%\')\\n    .height(\'100%\')\\n    .onReady((context: NavDestinationContext) => {\\n      // 注册动画\\n      ZRouter.animateMgr().registerAnimParam(this, context)\\n    })\\n    .onDisAppear(() => {\\n      // 取消注册动画\\n      ZRouter.animateMgr().unregisterAnim(this)\\n    }) // 设置NavAnimationModifier\\n    .attributeModifier(ZRouter.animateMgr().modifier(this))\\n  }\\n}\\n```\\n\\n#### 3. 查看效果\\n\\n![PixPin_2025-05-12_15-47-09](assets/PixPin_2025-05-12_15-47-09.gif)\\n\\n### 单个页面动画\\n\\n如果不想进行全局的页面跳转动画设置，可以给单个子页面进行设置，比如**Login** 页面\\n\\n**设置动画效果 和 注册、卸载动画函数**\\n\\n#### 1. 容器页面\\n\\n```typescript\\n// entry/src/main/ets/pages/Index.ets\\nimport {\\n  OpacityAnimateOptions,\\n  RotateAnimateOptions,\\n  Route,\\n  ScaleAnimateOptions,\\n  TranslateAnimationOptions,\\n  ZRouter\\n} from \'@hzw/zrouter\'\\n\\n@Entry\\n@Component\\nexport struct Index {\\n  build() {\\n    // 获取NavPathStack实例对象\\n    Navigation(ZRouter.getNavStack()) {\\n      Column({ space: 12 }) {\\n        Button(\'跳转到登录\').onClick((event: ClickEvent) => {\\n          ZRouter.getInstance().push(\\"Login\\")\\n        })\\n      }\\n    }\\n    .title(\'首页\')\\n    .height(\'100%\')\\n    .width(\'100%\')\\n    // 容器页面设置\\n    .customNavContentTransition(\\n      ZRouter\\n        .animateMgr()\\n        .getAnimCustomNavContentTransition())\\n  }\\n}\\n```\\n\\n#### 2. 登录页面\\n\\n```typescript\\n// entry/src/main/ets/pages/Login.ets\\nimport { Route, TranslateAnimationOptions, ZRouter } from \\"@hzw/zrouter\\";\\n\\n@Route({ name: \'Login\' })\\n@Component\\nexport struct Login {\\n  build() {\\n    NavDestination() {\\n      Column({ space: 12 }) {\\n        Text(\\"登录的页面\\")\\n      }\\n    }\\n    .title(\'登录\')\\n    .width(\'100%\')\\n    .height(\'100%\')\\n    .onReady((context: NavDestinationContext) => {\\n      ZRouter\\n        .animateMgr()\\n        .registerAnimParam(this, context)// 设置进场动画参数（比如动画时间，播放速度等）\\n        .setEnterAnimate({ duration: 500, curve: Curve.LinearOutSlowIn })// 设置退场动画参数（比如动画时间，播放速度等）\\n        .setExitAnimate({ duration: 500, curve: Curve.LinearOutSlowIn })// 添加平移动画\\n        .addAnimateOptions(new TranslateAnimationOptions({ y: \'100%\' }))\\n    })\\n    .onDisAppear(() => {\\n      // 取消注册动画\\n      ZRouter.animateMgr().unregisterAnim(this)\\n    }) // 设置NavAnimationModifier\\n    .attributeModifier(ZRouter.animateMgr().modifier(this))\\n\\n  }\\n}\\n```\\n\\n3. 效果\\n\\n![PixPin_2025-05-12_15-47-09](assets/PixPin_2025-05-12_15-47-09.gif)\\n\\n## 生命周期\\n\\nZRouter 也提供了项目开发必备的生命周期\\n\\n| 名称             | 解释         |\\n| ---------------- | ------------ |\\n| aboutToAppear    | 即将出现     |\\n| aboutToDisappear | 即将消失     |\\n| onWillAppear     | 在即将出现时 |\\n| onAppear         | 在出现时     |\\n| onWillShow       | 在即将展示时 |\\n| onShown          | 在已展示时   |\\n| onWillHide       | 在即将隐藏时 |\\n| onHidden         | 在已隐藏时   |\\n| onWillDisappear  | 在即将消失时 |\\n| onDisappear      | 在消失时     |\\n\\nZRouter 中提供了**3 种**使用生命周期的方式，差别不大，分别是**字面量**和**class**的以及**直接判断**\\n\\n### 字面量\\n\\n在需要使用生命周期的页面中，进行注册生命周期\\n\\n```typescript\\n// entry/src/main/ets/pages/Index.ets:1\\nimport { ILifecycleObserver, Lifecycle, LifecycleRegistry, Route, ZRouter } from \'@hzw/zrouter\'\\n\\n@Route({ name: \\"Index\\" })\\n@Entry\\n@Component\\nexport struct Index {\\n  // 1 声明生命周期注册器\\n  @Lifecycle lifecycle: LifecycleRegistry = LifecycleRegistry.create(this);\\n  tag = \\"Index \\"\\n\\n  aboutToAppear(): void {\\n    // 2、使用addObserver设置生命周期函数监听\\n    let that = this\\n    this.lifecycle.addObserver<ILifecycleObserver>({\\n      aboutToAppear: () => {\\n        console.log(`${that.tag}aboutToAppear`)\\n      },\\n      aboutToDisappear: () => {\\n        console.log(`${that.tag}aboutToDisappear`)\\n      },\\n      onWillAppear(r) {\\n        console.log(`${that.tag}onWillAppear`, r?.name, r?.navDestinationId)\\n      },\\n      onAppear(r) {\\n        console.log(`${that.tag}onAppear`, r?.name, r?.navDestinationId)\\n      },\\n      onWillShow(r) {\\n        console.log(`${that.tag}onWillShow `, r?.name, r?.navDestinationId)\\n      },\\n      onShown(r) {\\n        console.log(`${that.tag}onShown `, r?.name, r?.navDestinationId)\\n      },\\n      onWillHide(r) {\\n        console.log(`${that.tag}onWillHide `, r?.name, r?.navDestinationId)\\n      },\\n      onHidden(r) {\\n        console.log(`${that.tag}onHidden `, r?.name, r?.navDestinationId)\\n      },\\n      onWillDisappear(r) {\\n        console.log(`${that.tag}onWillDisappear `, r?.name, r?.navDestinationId)\\n      },\\n      onDisappear(r) {\\n        console.log(`${that.tag}onDisappear `, r?.name, r?.navDestinationId)\\n      }\\n    })\\n  }\\n\\n  build() {\\n    // 获取NavPathStack实例对象\\n    Navigation(ZRouter.getNavStack()) {\\n      Column({ space: 12 }) {\\n        Button(\'跳转到登录\').onClick((event: ClickEvent) => {\\n          ZRouter.getInstance().push(\\"Login\\")\\n        })\\n      }\\n    }\\n    .title(\'首页\')\\n    .height(\'100%\')\\n    .width(\'100%\')\\n\\n  }\\n}\\n```\\n\\n### class 的方式\\n\\n1. 用 class 的方式定义 class\\n\\n```typescript\\n// 1 定义生命周期class\\n@Observed\\nexport class LifecycleModel implements ILifecycleObserver {\\n  private tag = \\"class的生命周期: \\";\\n  loadState: string = \\"请求数据中...\\";\\n  counter: number = 0;\\n\\n  aboutToAppear(): void {\\n    console.log(this.tag + \\"aboutToAppear\\");\\n  }\\n\\n  aboutToDisappear(): void {\\n    console.log(this.tag + \\"aboutToDisappear\\");\\n  }\\n\\n  onWillAppear(info: RouterInfo): void {\\n    console.log(this.tag + \\"onWillAppear\\");\\n  }\\n\\n  onAppear(info: RouterInfo): void {\\n    console.log(this.tag + \\"onAppear\\");\\n    // 模拟请求数据\\n    setTimeout(() => {\\n      this.counter = 100;\\n    }, 3000);\\n  }\\n\\n  onWillShow(info: RouterInfo): void {\\n    console.log(this.tag + \\"onWillShow\\");\\n  }\\n\\n  onShown(info: RouterInfo): void {\\n    console.log(this.tag + \\"onShown\\");\\n  }\\n\\n  onWillHide(info: RouterInfo): void {\\n    console.log(this.tag + \\"onWillHide\\");\\n  }\\n\\n  onHidden(info: RouterInfo): void {\\n    console.log(this.tag + \\"onHidden\\");\\n  }\\n\\n  onWillDisappear(info: RouterInfo): void {\\n    console.log(this.tag + \\"onWillDisappear\\");\\n  }\\n\\n  onDisappear(info: RouterInfo): void {\\n    console.log(this.tag + \\"onDisappear\\");\\n  }\\n}\\n```\\n\\n2. 在页面中使用\\n\\n```typescript\\n@Route({ name: \\"Index\\" })\\n@Entry\\n@Component\\nexport struct Index {\\n  // 2 使用生命周期class\\n  @State viewModel: LifecycleModel = new LifecycleModel()\\n  @Lifecycle lifecycle: LifecycleRegistry = LifecycleRegistry.create(this);\\n\\n  aboutToAppear(): void {\\n    // 3 注册监听\\n    this.lifecycle.addObserver(this.viewModel)\\n  }\\n\\n  build() {\\n    // 获取NavPathStack实例对象\\n    Navigation(ZRouter.getNavStack()) {\\n      Column({ space: 12 }) {\\n        Button(\'跳转到登录\').onClick((event: ClickEvent) => {\\n          ZRouter.getInstance().push(\\"Login\\")\\n        })\\n      }\\n    }\\n    .title(\'首页\')\\n    .height(\'100%\')\\n    .width(\'100%\')\\n\\n  }\\n}\\n```\\n\\n### 直接判断\\n\\n通过 **this.lifecycle.addListener** 直接判断。\\n\\n```typescript\\n// entry/src/main/ets/pages/Index.ets:1\\nimport { Lifecycle, LifecycleRegistry, Route, ZRouter } from \'@hzw/zrouter\'\\n\\n\\n@Route({ name: \\"Index\\" })\\n@Entry\\n@Component\\nexport struct Index {\\n  @Lifecycle lifecycle: LifecycleRegistry = LifecycleRegistry.create(this);\\n\\n  aboutToAppear(): void {\\n    // 直接判定\\n    this.lifecycle.addListener((pageName, r) => {\\n      // pageName 生命周期函数的名字  aboutToAppear、onPageShow等\\n      console.log(\'--2--\', pageName, r?.name ?? \\"\\", r?.navDestinationId ?? \\"\\")\\n    })\\n  }\\n\\n  build() {\\n    // 获取NavPathStack实例对象\\n    Navigation(ZRouter.getNavStack()) {\\n      Column({ space: 12 }) {\\n        Button(\'跳转到登录\').onClick((event: ClickEvent) => {\\n          ZRouter.getInstance().push(\\"Login\\")\\n        })\\n      }\\n    }\\n    .title(\'首页\')\\n    .height(\'100%\')\\n    .width(\'100%\')\\n\\n  }\\n}\\n```\\n\\n##\\n\\n## 拦截器\\n\\n[ZRouter 支持多个拦截器和全局拦截](https://gitee.com/common-apps/ZRouter#%E6%8B%A6%E6%88%AA%E5%99%A8)器，在拦截器中可以做页面跳转的拦截，比如跳转前拦截、数据预取、登录拦截，404 拦截、埋点、自定义 URL 路径等等。\\n\\n| 拦截器           | 解释                              |\\n| ---------------- | --------------------------------- |\\n| onNavigateBefore | 在跳转之前回调                    |\\n| onRootWillShow   | Navigation 根视图显示时回调       |\\n| onPageWillShow   | 页面显示时回调                    |\\n| onNavigate       | 页面 push 或者 replace 跳转时回调 |\\n| onShowCallback   | 页面显示回调                      |\\n\\n![image-20250512172354900](assets/image-20250512172354900.png)\\n\\n### 常规使用\\n\\n#### 1. 定义拦截器 class\\n\\n```typescript\\n// entry/src/main/ets/utils/GlobalNavigateInterceptor.ets\\nimport {\\n  IGlobalNavigateInterceptor,\\n  DestinationInfo,\\n  InterceptorInfo,\\n  ZRouter,\\n  RedirectType,\\n} from \\"@hzw/zrouter\\";\\nimport { promptAction } from \\"@kit.ArkUI\\";\\n\\nexport class GlobalNavigateInterceptor implements IGlobalNavigateInterceptor {\\n  static count = 0;\\n  /**\\n   * 在跳转之前回调，可以在此回调中拦截跳转做一些自定义的逻辑，比如修改路由参数、数据预取、拦截跳转、拦截登录等场景\\n   * @param dest\\n   * @returns DestinationInfo#action 为NavigationAction.BLOCK 则表示拦截跳转，NEXT继续执行\\n   * @note\\n   * 如果通过ZRouter.getNavStack().push()方法跳转，则不会回调此方法,后续会考虑兼容\\n   * 只有通过ZRouter.getInstance().push()方法跳转时会回调此方法\\n   */\\n  onNavigateBefore: (destInfo: DestinationInfo) => Promise<DestinationInfo> = (\\n    destInfo\\n  ) => {\\n    console.log(\\"IInterceptor Global onNavigateBefore -> \\", destInfo.name);\\n    return new Promise((resolve, _) => {\\n      // 拦截页面1\\n      if (destInfo.name === \\"Login\\") {\\n        console.log(\\"拦截了登录页面\\");\\n        // 拦截跳转到Login页面\\n        if (GlobalNavigateInterceptor.count === 0) {\\n          // 自己定义的一些逻辑\\n          destInfo.param = \\" 在拦截器onNavigateBefore中已替换参数 \\";\\n          destInfo.next(); // 继续跳转 默认的 ，可以不写\\n        }\\n      }\\n      resolve(destInfo);\\n    });\\n  };\\n  /**\\n   * Navigation根视图显示时回调\\n   * @param fromContext\\n   */\\n  onRootWillShow: ((fromContext: NavDestinationContext) => void) | undefined = (\\n    fromContext\\n  ) => {\\n    console.log(\\n      \\"IInterceptor Global onRootWillShow: \\",\\n      fromContext.pathInfo.name\\n    );\\n  };\\n  /**\\n   * 页面显示时回调，当fromContext、toContext是一样时，则在NavBar根页面中启动的\\n   * @param fromContext\\n   * @param toContext\\n   */\\n  onPageWillShow:\\n    | ((\\n        fromContext: NavDestinationContext,\\n        toContext: NavDestinationContext\\n      ) => void)\\n    | undefined = (from, to) => {\\n    console.log(\\n      \\"IInterceptor Global onPageWillShow: \\",\\n      from,\\n      to.pathInfo.name,\\n      to.pathInfo.param\\n    );\\n  };\\n  /**\\n   * 页面push 或者 replace跳转时回调\\n   * @param context\\n   */\\n  onNavigate: ((context: InterceptorInfo) => void) | undefined = (info) => {\\n    if (info.notRegistered) {\\n      return;\\n    }\\n    console.log(\\"IInterceptor Global onNavigate -> \\", info.name);\\n    let isLogin = AppStorage.get<boolean>(\\"isLogin\\");\\n    if (info.isNeedLogin && !isLogin) {\\n      let param = info.param;\\n      ZRouter.getInstance()\\n        .setParam(param)\\n        .setAnimate(true)\\n        .setPopListener((result) => {\\n          if (result.data) {\\n            //  登录成功\\n            promptAction.showToast({ message: `登录成功` });\\n            return true; // 返回true 则继续跳转登录前的页面\\n          } else {\\n            return false;\\n          }\\n        })\\n        .redirect(\\"LoginPage\\", RedirectType.REPLACE);\\n    }\\n  };\\n  /**\\n   * 页面显示回调，鸿蒙sdk默认的，没有处理逻辑，如果其他的回调函数无法满足你的需求，可考虑在这里实现\\n   * @param context\\n   */\\n  onShowCallback: InterceptionShowCallback = (info) => {};\\n}\\n```\\n\\n#### 2. 注册使用\\n\\n```typescript\\n// entry/src/main/ets/pages/Index.ets:1\\nimport { Route, ZRouter } from \'@hzw/zrouter\'\\nimport { GlobalNavigateInterceptor } from \'../utils/GlobalNavigateInterceptor\';\\n\\n\\n@Route({ name: \\"Index\\" })\\n@Entry\\n@Component\\nexport struct Index {\\n  aboutToAppear(): void {\\n    // 添加拦截器\\n    ZRouter.setGlobalInterceptor(new GlobalNavigateInterceptor());\\n  }\\n\\n  build() {\\n    // 获取NavPathStack实例对象\\n    Navigation(ZRouter.getNavStack()) {\\n      Column({ space: 12 }) {\\n        Button(\'跳转到登录\').onClick((event: ClickEvent) => {\\n            // 此时会触发拦截器\\n          ZRouter.getInstance().push(\\"Login\\")\\n        })\\n      }\\n    }\\n    .title(\'首页\')\\n    .height(\'100%\')\\n    .width(\'100%\')\\n  }\\n}\\n```\\n\\n### needLogin\\n\\n普通的页面在使用装饰器 @Route 的时候，也可以传递一个属性`needlogin:boolean`，该属性会在拦截器中出现，我们可以结合该属性进行登录的权限校验。\\n\\n#### 1. 页面中使用\\n\\n![image-20250512190304099](assets/image-20250512190304099.png)\\n\\n然后当跳转到这个页面时，拦截器中的就可以获取到该属性\\n\\n```\\nZRouter.getInstance().push(\\"Cart\\")\\n```\\n\\n#### 2. 拦截器中处理\\n\\n![image-20250512190623863](assets/image-20250512190623863.png)\\n\\n## 携带参数跳转\\n\\n跳转页面的时候携带参数的写法比较简单\\n\\n### 1. 携带参数跳转 setParam\\n\\n```typescript\\n// entry/src/main/ets/pages/Index.ets:1\\nimport { Route, ZRouter } from \'@hzw/zrouter\'\\n\\n\\nexport interface IGoods {\\n  num: number\\n  name: string\\n}\\n\\n\\n@Route({ name: \\"Index\\" })\\n@Entry\\n@Component\\nexport struct Index {\\n  build() {\\n    // 获取NavPathStack实例对象\\n    Navigation(ZRouter.getNavStack()) {\\n      Column({ space: 12 }) {\\n        Button(\'跳转到登录\').onClick((event: ClickEvent) => {\\n          // ZRouter.getInstance().push(\\"Login\\")\\n          ZRouter.getInstance()\\n            .setParam({ num: 100, name: \\"手机\\" })\\n            .push(\\"Login\\")\\n        })\\n      }\\n    }\\n    .title(\'首页\')\\n    .height(\'100%\')\\n    .width(\'100%\')\\n\\n  }\\n}\\n```\\n\\n### 2. 获取页面参数 getParam\\n\\n```typescript\\n// entry/src/main/ets/pages/Login.ets\\nimport { Route, TranslateAnimationOptions, ZRouter } from \\"@hzw/zrouter\\";\\nimport { IGoods } from \\"./Index\\";\\n\\n@Route({ name: \'Login\' })\\n@Component\\nexport struct Login {\\n  build() {\\n    NavDestination() {\\n      Column({ space: 12 }) {\\n        Text(\\"登录的页面\\")\\n      }\\n    }\\n    .title(\'登录\')\\n    .width(\'100%\')\\n    .height(\'100%\')\\n    .onReady((context: NavDestinationContext) => {\\n      const param = ZRouter.getInstance().getParam() as IGoods\\n      console.log(\\"参数\\", param.num, param.name)\\n\\n    })\\n\\n  }\\n}\\n\\n```\\n\\n## 跨模块跳转\\n\\n这里演示两个模块，一个是**hap-entry**，另外一个是**hsp-**library，演示**entry**跳转到 library 模块。\\n\\n### 1. 项目中新建 hsp 模块-library\\n\\n![image-20250512211855945](assets/image-20250512211855945.png)\\n\\n### 2. library 模块下载 ZRouter `library/oh-package.json5`\\n\\n```json\\n  \\"dependencies\\": {\\n    \\"@hzw/zrouter\\": \\"^1.4.1\\",\\n  }\\n```\\n\\n### 3. **library**模块在 **`hvigorfile.ts`** 导入 **router-register-plugin**\\n\\n```typescript\\n// library/hvigorfile.ts\\nimport { hspTasks } from \\"@ohos/hvigor-ohos-plugin\\";\\nimport { routerRegisterPlugin, PluginConfig } from \\"router-register-plugin\\";\\n\\n// 2、初始化配置\\nconst config: PluginConfig = {\\n  scanDirs: [\\"src/main/ets/pages\\", \\"src/main/ets/views\\"], // 扫描的目录，如果不设置，默认是扫描src/main/ets目录\\n  logEnabled: true, // 查看日志\\n  viewNodeInfo: false, // 查看节点信息\\n  isAutoDeleteHistoryFiles: true, // 删除无用编译产物\\n  lifecycleObserverAttributeName: \\"xxx\\", // 可选，设置全局的生命周期实现类在组件上的属性名，默认值是lifecycleObserver\\n};\\n\\nexport default {\\n  system: hspTasks /* Built-in plugin of Hvigor. It cannot be modified. */,\\n  plugins: [\\n    routerRegisterPlugin(config),\\n  ] /* Custom plugin to extend the functionality of Hvigor. */,\\n};\\n```\\n\\n### 4. **library**模块新建 Info 页面\\n\\n```typescript\\n// library/src/main/ets/pages/Info.ets\\nimport { Route } from \\"@hzw/zrouter\\"\\n\\n@Route({ name: \\"Info\\" })\\n@Component\\nexport struct Info {\\n  build() {\\n    NavDestination() {\\n      Column() {\\n        Button(\'Info\')\\n      }\\n      .width(\\"100%\\")\\n      .height(\\"100%\\")\\n      .justifyContent(FlexAlign.Center)\\n    }\\n  }\\n}\\n```\\n\\n### 5. entry 模块引入其他模块 `entry/oh-package.json5`\\n\\n```json\\n  \\"dependencies\\": {\\n    \\"@hzw/zrouter\\": \\"^1.4.1\\",\\n    \\"library\\": \\"file:../library\\"\\n  },\\n```\\n\\n### 6. 进行页面跳转\\n\\n```typescript\\n// entry/src/main/ets/pages/Index.ets:1\\nimport { Route, ZRouter } from \'@hzw/zrouter\'\\nimport { GlobalNavigateInterceptor } from \'../utils/GlobalNavigateInterceptor\';\\n\\nexport interface I13 {\\n  id: number;\\n  name: string\\n}\\n\\n@Route({ name: \\"Index\\" })\\n@Entry\\n@Component\\nexport struct Index {\\n  aboutToAppear(): void {\\n    // 添加拦截器\\n    ZRouter.setGlobalInterceptor(new GlobalNavigateInterceptor());\\n  }\\n\\n  build() {\\n    // 获取NavPathStack实例对象\\n    Navigation(ZRouter.getNavStack()) {\\n      Column({ space: 12 }) {\\n        Button(\'跳转到登录\').onClick((event: ClickEvent) => {\\n          ZRouter.getInstance().push(\\"Login\\")\\n        })\\n        Button(\'跳转到购物车\').onClick((event: ClickEvent) => {\\n          ZRouter.getInstance().push(\\"Cart\\")\\n        })\\n        Button(\\"跳转到商品详情页面\\")\\n          .onClick(() => {\\n            ZRouter.getInstance().setParam({\\n              id: 1,\\n              name: \\"商品1\\"\\n            })\\n              .push(\\"Goods\\")\\n          })\\n\\n        Button(\'跳转到信息详情页面\').onClick((event: ClickEvent) => {\\n          ZRouter.getInstance().push(\\"Info\\")\\n        })\\n      }\\n    }\\n    .title(\'首页\')\\n    .height(\'100%\')\\n    .width(\'100%\')\\n\\n  }\\n}\\n```\\n\\n### 7. 效果\\n\\n![PixPin_2025-05-12_21-28-06](assets/PixPin_2025-05-12_21-28-06.gif)\\n\\n## NavDestination 页面模板化能力\\n\\n页面模板能力可以让我们不需要每一个页面都添加 NavNavigation 组件，提高我们的开发效率。\\n\\n在@Route 注解中使用 useTemplate 即可使用页面模板化能力，如：\\n\\n```typescript\\nimport { Route } from \\"@hzw/zrouter\\"\\n\\n@Route({ name: \\"Demo\\", useTemplate: true, title: \\"DemoTitle\\" })\\n@Component\\nexport struct Demo {\\n  build() {\\n    Column() {\\n      Button(\'Demo\')\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n## 接口列表\\n\\n- ZRouter: 是路由管理器，包括了初始化、路由操作、服务路由、生命周期、拦截器、模板化、动画等功能的管理\\n- NavDestBuilder: 路由的进出栈管理，主要包括跳转、返回、替换、移除等操作。\\n\\n### ZRouter 类接口\\n\\n| 方法名                       | 描述                                                   | 参数                                                                                | 返回值                         | 废弃状态 |\\n| ---------------------------- | ------------------------------------------------------ | ----------------------------------------------------------------------------------- | ------------------------------ | -------- |\\n| `initialize`                 | 初始化路由，可传入一个配置函数                         | `invoke?: ((config: ConfigInitializer) => void)`                                    | `void`                         | 否       |\\n| `setModuleLoadedListener`    | 设置模块加载完成的监听器，在使用了服务路由会生效       | `listener: () => void`                                                              | `void`                         | 否       |\\n| `isDynamicLoadedComplete`    | 判断模块是否动态加载完成                               | 无                                                                                  | `boolean`                      | 否       |\\n| `getInstance`                | 获取路由操作的实例，用于进行跳转、返回等操作           | `stackName: string = DEFAULT_STACK_NAME`                                            | `NavDestBuilder<ObjectOrNull>` | 否       |\\n| `addService`                 | 添加服务路由，外部不需要手动调用，会在编译阶段自动注册 | `name: string`, `service: IProvider`                                                | `void`                         | 否       |\\n| `getService`                 | 获取服务路由管理类                                     | `name: string`                                                                      | `T extends IProvider null`     | 否       |\\n| `animateMgr`                 | 获取动画管理类                                         | 无                                                                                  | `NavAnimationMgr`              | 否       |\\n| `registerNavStack`           | 注册路由栈                                             | `stackName: string = DEFAULT_STACK_NAME`, `pathStack: NavPathStack`                 | `void`                         | 否       |\\n| `unregisterNavStack`         | 解除注册路由栈                                         | `stackName: string`                                                                 | `void`                         | 否       |\\n| `getNavStack`                | 获取默认栈名的路由栈                                   | `willShow?: InterceptionShowCallback`                                               | `NavPathStack`                 | 否       |\\n| `getNavStackByName`          | 根据栈名获取路由栈，通常用不上                         | `stackName: string`                                                                 | `NavPathStack`                 | 否       |\\n| `getCurrentNavStack`         | 获取当前路由栈实例                                     | 无                                                                                  | `NavPathStack`                 | 否       |\\n| `getLastNavDestinationId`    | 获取当前路由栈的栈顶页面 `DestinationId`               | 无                                                                                  | `string or undefined`          | 否       |\\n| `setGlobalInterceptor`       | 设置全局拦截器                                         | `interceptor: IGlobalNavigateInterceptor`, `stackName: string = DEFAULT_STACK_NAME` | `void`                         | 否       |\\n| `setInterceptor`             | 添加拦截器                                             | `interceptor: T extends IInterceptor`, `stackName: string = DEFAULT_STACK_NAME`     | `void`                         | 否       |\\n| `removeInterceptor`          | 移除拦截器                                             | `interceptor: T extends IInterceptor`, `stackName: string = DEFAULT_STACK_NAME`     | `boolean`                      | 否       |\\n| `addGlobalLifecycleObserver` | 添加全局的 `NavDestination` 页面的生命周期观察者       | `observer: IL extends ILifecycleObserver`                                           | 未明确                         | 否       |\\n| `addLifecycleObserver`       | 添加单个 `NavDestination` 页面的生命周期观察者         | `observer: LifecycleObserver`                                                       | 未明确                         | 否       |\\n| `templateMgr`                | 获取 `NavDestination` 页面模板管理器，通常用不上       | 无                                                                                  | `TemplateMgr`                  | 否       |\\n| `getCurrentStackName`        | 获取当前路由栈名称                                     | 无                                                                                  | `string`                       | 否       |\\n| `getParamByKey`              | 获取路由参数，建议带上默认值和泛型                     | `key: string`, `defVal: ObjectOrNull = null`                                        | `P = ObjectOrNull`             | 否       |\\n\\n### NavDestBuilder 类接口\\n\\n| 方法名           | 描述                                                                                       | 参数                                           | 返回值              | 废弃状态 |\\n| ---------------- | ------------------------------------------------------------------------------------------ | ---------------------------------------------- | ------------------- | -------- |\\n| `setAnimate`     | 设置是否启动动画                                                                           | `animated: boolean`                            | `NavDestBuilder<T>` | 否       |\\n| `setLaunchMode`  | 设置启动模式，api12 起才会生效                                                             | `mode: LaunchMode`                             | `NavDestBuilder<T>` | 否       |\\n| `setParam`       | 设置页面跳转携带的参数，通过`getParam`获取参数                                             | `param: ObjectOrNull`                          | `NavDestBuilder<T>` | 否       |\\n| `withParam`      | 设置页面跳转携带的参数，key-value 形式，建议使用，通过`ZRouter.getParamByKey(key)`获取参数 | `key: string`, `value: ObjectOrNull`           | `NavDestBuilder<T>` | 否       |\\n| `setPopListener` | 监听页面返回携带的结果，所有页面返回结果都会回调着                                         | `callback: OnPopResultCallback<TObjectOrNull>` | `NavDestBuilder<T>` | 否       |\\n\\n## 总结\\n\\nZRouter作为鸿蒙生态中流行的路由管理库，为HarmonyOS Next应用提供了简洁而强大的路由解决方案。它的主要优势包括：\\n\\n1. **简单易用**：ZRouter提供链式API调用，使代码更简洁直观，降低开发者的使用门槛。\\n   \\n2. **丰富的动画效果**：内置多种转场动画（平移、旋转、渐变、缩放等），并支持自定义，使页面切换更加流畅美观。\\n\\n3. **强大的拦截器机制**：可实现页面重定向、登录验证、埋点统计等复杂业务场景。\\n\\n4. **完善的生命周期管理**：提供丰富的生命周期函数，让任意类都能享有与组件相同的生命周期特性。\\n\\n5. **跨模块通信能力**：支持服务路由，实现Har/Hsp模块间的无缝通信。\\n\\n6. **页面模板化**：通过@Route注解和useTemplate配置，提高开发效率和代码复用率。\\n\\n7. **兼容性和可扩展性**：支持与现有Navigation无缝融合，实现零成本迁移；适用于ArkUI-X跨平台开发。\\n\\nZRouter的设计思路遵循简洁、高效、可扩展的原则，为鸿蒙应用开发者提供了一套完整的路由解决方案，极大地简化了页面跳转、参数传递和页面生命周期管理的复杂性，是构建大型HarmonyOS应用的理想选择。\\n"}'),c={name:"鸿蒙开发技巧/HarmonyOS Next 路由跳转 ZRouter/HarmonyOS Next 路由跳转 ZRouter.md"};function y(u,s,b,F,m,C){return a(),l("div",null,[...s[0]||(s[0]=[t("",130)])])}const v=n(c,[["render",y]]);export{B as __pageData,v as default};
